html:
{%- set property = frappe.get_doc("JH Property Master", doc.property) -%}

{%- set cheque_list = doc.cheque_details or [] -%}

{%- set charges_list = doc.table_xqmr or [] -%}

{%- set rent_diff = (doc.proposed_rent or 0) - (doc.current_rent or 0) -%}

{%- set grand_total = (doc.proposed_rent or 0) + (doc.additional_charges or 0) -%}

{%- set row_ns = namespace(max_rows=5, total=0) -%}

{%- if charges_list|length > row_ns.max_rows -%}

  {%- set row_ns.max_rows = charges_list|length -%}

{%- endif -%}

{%- if cheque_list|length > row_ns.max_rows -%}

  {%- set row_ns.max_rows = cheque_list|length -%}

{%- endif -%}

{%- for c in cheque_list -%}

  {%- set row_ns.total = row_ns.total + (c.cheque_amount or 0) -%}

{%- endfor -%}

{%- set settings = frappe.get_doc("JH Digitrack Settings", "JH Digitrack Settings") -%}

{%- set prop_approvers = frappe.get_all(

      "JH Property Approver",

      filters={"parent": doc.property, "parenttype": "JH Property Master"},

      fields=["order", "approver"],

      order_by="`order` asc",

      ignore_permissions=True

    ) -%}

{%- set approval_ns = namespace(approved=[]) -%}

{%- for trail in doc.audit_trail -%}

  {%- if trail.action == "Approve" -%}

    {%- set approval_ns.approved = approval_ns.approved + [trail.current_state] -%}

  {%- endif -%}

{%- endfor -%}

{%- set prop_type_raw = doc.property_type or property.type_of_property or "" -%}

{%- if prop_type_raw == "Other" and property.other_property_type -%}

  {%- set display_type = "Other - " ~ property.other_property_type -%}

{%- else -%}

  {%- set display_type = prop_type_raw -%}

{%- endif -%}

{%- set show_md = "Pending MD" in approval_ns.approved or doc.workflow_state == "Pending MD" -%}

{%- set box_ns = namespace(count=prop_approvers|length + 3) -%}

{%- if show_md -%}

  {%- set box_ns.count = box_ns.count + 1 -%}

{%- endif -%}

{%- set box_width = (100 / box_ns.count)|round(4) -%}

<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Rent Payment Request</title>
<style>

  @page { size: A4 landscape; margin: 5mm; }

  * { box-sizing: border-box; }

  body { margin: 0; padding: 0; font-family: "Times New Roman", serif; font-size: 9px; }

  table { border-collapse: collapse; width: 100%; table-layout: fixed; }

  td { border: 1px solid #000; padding: 1px 3px; font-size: 9px; vertical-align: middle; line-height: 1.3; }

  .center { text-align: center; }

  .right { text-align: right; }

  .bold { font-weight: bold; }

  .yellow { background: #fff200; }

  .cream { background: #f6e3a1; }
</style>
</head>
<body>

<!-- ═══ MAIN TABLE ═══ -->
<table>
<colgroup><col span="8" style="width:12.5%"></colgroup>

  <tr>
<td rowspan="2"><img src="files/jhLogo.png"></td>
<td colspan="5" class="center bold" style="font-size:12px;">JALEEL HOLDINGS L.L.C - U.A.E</td>
<td colspan="2" class="bold">SL.No: {{ doc.name }}</td>
</tr>
<tr>
<td colspan="7" class="yellow center bold" style="height:18px; color:#c62828; font-size:11px;">

      Rent Payment Request. ({{ display_type | upper }})
</td>
</tr>

  <tr>
<td>Co Code</td>
<td colspan="3">{{ property.booked_under or "" }}</td>
<td>Land Lord</td>
<td colspan="3">{{ doc.landlord or property.landlord or "" }}</td>
</tr>
<tr>
<td>Profit Centre</td>
<td colspan="3">{{ property.profit_center or "" }}</td>
<td>Real Estate</td>
<td colspan="3">{{ property.real_estate or "" }}</td>
</tr>
<tr>
<td>Location</td>
<td colspan="3">{{ doc.location or property.location or "" }}</td>
<td>Property Type</td>
<td colspan="3">{{ display_type }}</td>
</tr>
<tr>
<td>Emirate</td>
<td colspan="3">{{ doc.emirate or property.emirate or "" }}</td>
<td>Area [Sqft/Mtr]</td>
<td colspan="3">{{ doc.area_sqftmtr or property.area_sqftmtr or "" }}</td>
</tr>
  <tr>
    <td>Rent period</td>
    <td colspan="3">{{ frappe.format_date(doc.renewal_from) }} to {{ frappe.format_date(doc.renewal_to) }}</td>
    <td>PO Number</td>
    <td colspan="3">{{ doc.po_number or "" }}</td>
  </tr>
   <tr>
    <td colspan="2">MIRO Numbers</td>
    <td colspan="6">{{ (doc.table_gfwd or []) | map(attribute="miro_number") | select | join(", ") }}</td>
  </tr>
  <tr>
<td colspan="8" class="cream center bold">Payment details.</td>
</tr>
<tr class="cream bold center">
<td>Particulars</td>
<td>Amount</td>
<td colspan="2">Remarks</td>
<td>Type</td>
<td>Date</td>
<td>Amount</td>
<td >Cheque In Favour of</td>
</tr>

  {%- for i in range(row_ns.max_rows) -%}
<tr>
{%- if i < charges_list|length -%}
  {%- set ch = charges_list[i] -%}
  <td>{{ ch.label or "" }}</td>
  <td class="right">{% if ch.amount %}{{ "{:,.2f}".format(ch.amount) }}{% endif %}</td>
{%- else -%}
  <td></td><td></td>
{%- endif -%}

{%- if i == 0 -%}
  <td colspan="2" rowspan="{{ row_ns.max_rows }}"></td>
{%- endif -%}

{%- if i < cheque_list|length -%}
  {%- set c = cheque_list[i] -%}
  <td class="center">{{ c.cheque_type or "" }}</td>
  <td class="center">{{ frappe.format_date(c.cheque_date) if c.cheque_date else "" }}</td>
  <td class="right">{{ "{:,.2f}".format(c.cheque_amount or 0) }}</td>
{%- else -%}
  <td></td><td></td><td></td>
{%- endif -%}

{%- if i < cheque_list|length -%}
  {%- set c = cheque_list[i] -%}
  <td class="center">{{ c.payee or "" }}</td>



{%- else -%}
  <td></td><td></td><td></td><td></td>
{%- endif -%}
</tr>

  {%- endfor -%}

  <tr class="bold">
<td colspan="5"></td>
<td colspan="2" class="center">Total Amount</td>
<td class="right">{{ "{:,.2f}".format(row_ns.total) }}</td>
</tr>

  <tr>
<td rowspan="2" class="cream bold">Rent Comparison</td>
<td>Current Year Rent</td>
<td>Previous Year Rent</td>
<td>Rent Increase / (Decrease)</td>
<td>% Of Inc./(Decr.)</td>
<td></td><td></td><td></td>
</tr>
<tr>
<td class="center">{{ "{:,.2f}".format(doc.proposed_rent or 0) }}</td>
<td class="center">{{ "{:,.2f}".format(doc.current_rent or 0) }}</td>
<td class="center">{{ "{:,.2f}".format(rent_diff) }}</td>
<td class="center">{{ "{:.2f}".format(doc.rent_change_percent or 0) }}%</td>
<td></td><td></td><td></td>
</tr>

  <tr>
<td rowspan="2" class="cream bold">Remarks</td>
<td rowspan="2" colspan="2" class="center">{{ doc.remarks or "" }}</td>
<td colspan="2" class="center">Negotiated by</td>
<td></td><td></td><td></td>
</tr>
<tr>
<td colspan="2" class="center">Property department</td>
<td></td><td></td><td></td>
</tr>

  <!-- Approval Trail header stays inside main table -->
<tr>
<td colspan="8" class="cream center bold" style="padding:2px; border-bottom:none;">Approval Trail</td>
</tr>

</table>
<!-- ═══ END MAIN TABLE ═══ -->


<!-- ═══ APPROVAL BOXES TABLE — sibling, explicit equal widths via colgroup ═══ -->
<table style="width:100%; border-collapse:collapse; table-layout:fixed; margin-top:-1px;">
<colgroup>

    {%- for i in range(box_ns.count) -%}
<col style="width:{{ box_width }}%">

    {%- endfor -%}
</colgroup>
<tr>

    {%- for row in prop_approvers -%}
<td style="border:1px solid #000; border-top:none; text-align:center; padding:3px; vertical-align:top; height:50px;">
<div style="font-size:8px; font-weight:bold; border-bottom:1px solid #ccc; padding-bottom:1px; margin-bottom:2px;">Approver {{ row.order }}</div>
<div style="font-size:9px; margin-bottom:2px;">{{ frappe.db.get_value("User", row.approver, "full_name") or row.approver or "—" }}</div>

      {%- if ("Pending Approver " ~ row.order) in approval_ns.approved -%}
<div style="font-size:8px; color:green; font-weight:bold;">✓ Approved</div>

      {%- else -%}
<div style="font-size:8px; color:#aaa;">—</div>

      {%- endif -%}
</td>

    {%- endfor -%}
<td style="border:1px solid #000; border-top:none; text-align:center; padding:3px; vertical-align:top; height:50px;">
<div style="font-size:8px; font-weight:bold; border-bottom:1px solid #ccc; padding-bottom:1px; margin-bottom:2px;">Admin HOD</div>
<div style="font-size:9px; margin-bottom:2px;">{{ frappe.db.get_value("User", settings.admin_hod_user, "full_name") or settings.admin_hod_user or "—" }}</div>

      {%- if "Pending Admin HOD" in approval_ns.approved -%}
<div style="font-size:8px; color:green; font-weight:bold;">✓ Approved</div>

      {%- else -%}<div style="font-size:8px; color:#aaa;">—</div>

      {%- endif -%}
</td>
<td style="border:1px solid #000; border-top:none; text-align:center; padding:3px; vertical-align:top; height:50px;">
<div style="font-size:8px; font-weight:bold; border-bottom:1px solid #ccc; padding-bottom:1px; margin-bottom:2px;">FC</div>
<div style="font-size:9px; margin-bottom:2px;">{{ frappe.db.get_value("User", settings.fc_user, "full_name") or settings.fc_user or "—" }}</div>

      {%- if "Pending FC" in approval_ns.approved -%}
<div style="font-size:8px; color:green; font-weight:bold;">✓ Approved</div>

      {%- else -%}<div style="font-size:8px; color:#aaa;">—</div>

      {%- endif -%}
</td>
<td style="border:1px solid #000; border-top:none; text-align:center; padding:3px; vertical-align:top; height:50px;">
<div style="font-size:8px; font-weight:bold; border-bottom:1px solid #ccc; padding-bottom:1px; margin-bottom:2px;">CFO</div>
<div style="font-size:9px; margin-bottom:2px;">{{ frappe.db.get_value("User", settings.cfo_user, "full_name") or settings.cfo_user or "—" }}</div>

      {%- if "Pending CFO" in approval_ns.approved -%}
<div style="font-size:8px; color:green; font-weight:bold;">✓ Approved</div>

      {%- else -%}<div style="font-size:8px; color:#aaa;">—</div>

      {%- endif -%}
</td>

    {%- if show_md -%}
<td style="border:1px solid #000; border-top:none; text-align:center; padding:3px; vertical-align:top; height:50px;">
<div style="font-size:8px; font-weight:bold; border-bottom:1px solid #ccc; padding-bottom:1px; margin-bottom:2px;">MD</div>
<div style="font-size:9px; margin-bottom:2px;">{{ frappe.db.get_value("User", settings.md_user, "full_name") or settings.md_user or "—" }}</div>

      {%- if "Pending MD" in approval_ns.approved -%}
<div style="font-size:8px; color:green; font-weight:bold;">✓ Approved</div>

      {%- else -%}<div style="font-size:8px; color:#aaa;">—</div>

      {%- endif -%}
</td>

    {%- endif -%}
</tr>
</table>

<div style="page-break-before: always;"></div>

<!-- ===== PAGE 2 : Audit Trail ===== -->
<table>
  <tr>
    <td colspan="5" class="cream center bold" style="height:20px;">Approval Audit Trail</td>
  </tr>
  <tr class="cream bold center">
    <td style="width:5%;">Sr</td>
    <td style="width:28%;">User</td>
    <td style="width:17%;">Role</td>
    <td style="width:12%;">Action</td>
    <td style="width:38%;">Comments</td>
  </tr>
  {%- for trail in doc.audit_trail -%}
  <tr>
    <td class="center">{{ loop.index }}</td>
    <td style="padding-left:3px;">{{ trail.user or "" }}</td>
    <td style="padding-left:3px;">{{ trail.role or "" }}</td>
    <td class="center">{{ trail.action or "" }}</td>
    <td style="padding-left:3px;">{{ trail.comments or "" }}</td>
  </tr>
  {%- endfor -%}
</table>

</body>
</html>
